cion_origen":"D.O.Ca. Rioja","ubicacion_pais":"España","ubicacion_region":"Rioja","ubicacion_pais_en":"Spain","ubicacion_pais_fr":"Espagne","ubicacion_region_en":"Rioja","ubicacion_region_fr":"Rioja"},"despues":{"categoria":"VINOS TINTOS — RIOJA","categoria_en":"Red Wines — Rioja","categoria_fr":"Vins rouges — Rioja","denominacion_origen":"D.O.Ca. Rioja","ubicacion_pais":"España","ubicacion_region":"La Rioja","ubicacion_pais_en":"Spain","ubicacion_pais_fr":"Espagne","ubicacion_region_en":"La Rioja","ubicacion_region_fr":"La Rioja"}}]$data$::jsonb;
BEGIN
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(cambios) c LEFT JOIN public."Vinos" v ON v.id = c->>'id' WHERE v.id IS NULL OR NOT (to_jsonb(v) @> (c->'antes') OR to_jsonb(v) @> (c->'despues'))) THEN
  RAISE EXCEPTION 'El catálogo ha cambiado: revisar antes de aplicar la auditoría';
 END IF;
 UPDATE public."Vinos" v SET
 categoria = c->'despues'->>'categoria',
 categoria_en = c->'despues'->>'categoria_en',
 categoria_fr = c->'despues'->>'categoria_fr',
 denominacion_origen = c->'despues'->>'denominacion_origen',
 ubicacion_pais = c->'despues'->>'ubicacion_pais',
 ubicacion_region = c->'despues'->>'ubicacion_region',
 ubicacion_pais_en = c->'despues'->>'ubicacion_pais_en',
 ubicacion_pais_fr = c->'despues'->>'ubicacion_pais_fr',
 ubicacion_region_en = c->'despues'->>'ubicacion_region_en',
 ubicacion_region_fr = c->'despues'->>'ubicacion_region_fr'
 FROM jsonb_array_elements(cambios) c
 WHERE v.id=c->>'id' AND to_jsonb(v) @> (c->'antes') AND NOT to_jsonb(v) @> (c->'despues');
END
$audit$;
COMMIT;
